const https = require('https');
const fs = require('fs');

const jobId = $('Code in JavaScript2').item.json.jobId;
const videoPath = $('Code in JavaScript2').item.json.videoPath;
const pageId = 'TU_FACEBOOK_PAGE_ID';
const accessToken = 'TU_FACEBOOK_PAGE_ACCESS_TOKEN';
const titulo = $('Code in JavaScript').item.json.titulo;
const descripcion = $('Code in JavaScript').item.json.descripcion;
const hashtags = $('Code in JavaScript').item.json.hashtags;

const videoData = fs.readFileSync(videoPath);
const boundary = 'boundary' + Date.now();

const description = titulo + '\n\n' + descripcion + '\n\n' + hashtags;

const result = await new Promise((resolve, reject) => {
  const options = {
    hostname: 'graph-video.facebook.com',
    path: '/v19.0/' + pageId + '/videos',
    method: 'POST',
    headers: {
      'Content-Type': 'multipart/form-data; boundary=' + boundary
    }
  };

  const req = https.request(options, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => {
      try { resolve(JSON.parse(data)); }
      catch(e) { resolve({ raw: data }); }
    });
  });

  req.on('error', reject);

  const header = '--' + boundary + '\r\n' +
    'Content-Disposition: form-data; name="access_token"\r\n\r\n' + accessToken + '\r\n' +
    '--' + boundary + '\r\n' +
    'Content-Disposition: form-data; name="description"\r\n\r\n' + description + '\r\n' +
    '--' + boundary + '\r\n' +
    'Content-Disposition: form-data; name="file"; filename="' + jobId + '.mp4"\r\n' +
    'Content-Type: video/mp4\r\n\r\n';

  const footer = '\r\n--' + boundary + '--';

  req.write(header);
  req.write(videoData);
  req.write(footer);
  req.end();
});

return [{ json: result }];

