const { exec } = require('child_process');
const https = require('https');
const http = require('http');
const fs = require('fs');

const jobId = $('Code in JavaScript').item.json.jobId;
const photos = $('Code in JavaScript1').all();
const guionTexto = $('Code in JavaScript').item.json.guionTexto;

const downloadFile = (url, dest) => new Promise((resolve, reject) => {
  const file = fs.createWriteStream(dest);
  const protocol = url.startsWith('https') ? https : http;
  protocol.get(url, (response) => {
    if (response.statusCode === 301 || response.statusCode === 302) {
      file.close();
      return downloadFile(response.headers.location, dest).then(resolve).catch(reject);
    }
    response.pipe(file);
    file.on('finish', () => file.close(resolve));
  }).on('error', (err) => {
    fs.unlink(dest, () => {});
    reject(err);
  });
});

const downloadAudio = (text, dest, apiKey) => new Promise((resolve, reject) => {
  const body = JSON.stringify({ model: 'tts-1', input: text, voice: 'nova', response_format: 'mp3' });
  const options = {
    hostname: 'api.openai.com',
    path: '/v1/audio/speech',
    method: 'POST',
    headers: {
      'Authorization': 'Bearer ' + apiKey,
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(body)
    }
  };
  const file = fs.createWriteStream(dest);
  const req = https.request(options, (response) => {
    response.pipe(file);
    file.on('finish', () => file.close(resolve));
  });
  req.on('error', reject);
  req.write(body);
  req.end();
});

const imageDir = 'C:\\Users\\Public\\n8n-videos\\images';
