const concat = imagePaths.map((_, i) => '[v' + i + ']').join('') + 'concat=n=' + imagePaths.length + ':v=1:a=0[vout]';
const command = 'ffmpeg -y ' + inputs + ' -i "' + audioPath + '" -filter_complex "' + filters + ';' + concat + '" -map "[vout]" -map ' + imagePaths.length + ':a -c:v libx264 -preset fast -crf 23 -c:a aac -b:a 128k -pix_fmt yuv420p -shortest "' + outputPath + '"';

